  /// </summary>
  [pbr::OriginalName("BATTLE_ACTION_ITEM")] BattleActionItem = 4,
  /// <summary>
  /// 逃跑(PVE 可用;成功率基于速度差)
  /// </summary>
  [pbr::OriginalName("BATTLE_ACTION_FLEE")] BattleActionFlee = 5,
  /// <summary>
