  /// </summary>
  [pbr::OriginalName("BATTLE_HIT_COMBO")] BattleHitCombo = 1,
  /// <summary>
  /// 反击(受击者还手的 ATTACK / DAMAGE)
  /// </summary>
  [pbr::OriginalName("BATTLE_HIT_COUNTER")] BattleHitCounter = 2,
  /// <summary>
  /// 反震(DAMAGE:source=受击者,target=出手者)
  /// </summary>
  [pbr::OriginalName("BATTLE_HIT_REFLECT")] BattleHitReflect = 3,
  [pbr::OriginalName("BATTLE_HIT_PURSUIT")] BattleHitPursuit = 4,
  [pbr::OriginalName("BATTLE_HIT_MIRROR")] BattleHitMirror = 5,
}

/// <summary>
/// ---- 胜负 ----
/// </summary>
public enum eBattleOutcome {
  [pbr::OriginalName("BATTLE_OUTCOME_ONGOING")] BattleOutcomeOngoing = 0,
  /// <summary>
  /// team_index 0 胜
  /// </summary>
  [pbr::OriginalName("BATTLE_OUTCOME_SIDE_A_WIN")] BattleOutcomeSideAWin = 1,
  [pbr::OriginalName("BATTLE_OUTCOME_SIDE_B_WIN")] BattleOutcomeSideBWin = 2,
  /// <summary>
  /// 回合打满等平局情形(PVE 中进攻方判负走 SIDE_B_WIN)
  /// </summary>
  [pbr::OriginalName("BATTLE_OUTCOME_DRAW")] BattleOutcomeDraw = 3,
  /// <summary>
  /// 作废:Match 为这一局写了唯一的 ABORT(执行进程失效、截止作废、帮会取消、人工处置等),全员没有任何效果。
  /// 只由 Match 在 ABORT 事务里写进「作废结算」,battle 引擎永远不产出;客户端收到后退出战斗、提示本局作废
  /// (docs/design/battle-instance-loss-early-abort.md §5、§6)。
  /// </summary>
  [pbr::OriginalName("BATTLE_OUTCOME_VOID")] BattleOutcomeVoid = 4,
}

/// <summary>
/// ---- 活动对局上下文(帮会同道历练,docs/design/guild-phase2/06-activities.md §6.17) ----
/// 流向:guild 组装 → match MatchInternal.StartActivityBattle 校验后原样放进 CreateBattleRequest.activity_context
///       → battle 存进房间、结算时原样回显进 contracts.kafka.BattleResultEvent.activity_context → guild 消费结算。
/// battle / scene 不解释其中任何业务字段(只看 kind 是否为 NONE 来决定是否走持久化结果通道,§6.19)。
/// 本段只在文件末尾追加(属性会话也在改本文件)。
/// </summary>
public enum eBattleActivityKind {
  /// <summary>
  /// 普通对局:不回显上下文,结果事件照旧只发一次
  /// </summary>
  [pbr::OriginalName("BATTLE_ACTIVITY_KIND_NONE")] BattleActivityKindNone = 0,
  /// <summary>
  /// 帮会同道历练:go/guild 以消费组 guild-trial 消费 match-results 结算
  /// </summary>
  [pbr::OriginalName("BATTLE_ACTIVITY_KIND_GUILD_TRIAL")] BattleActivityKindGuildTrial = 1,
}

/// <summary>
/// 观战可见性(docs/design/battle-spectate-tiered-fanout.md §10 第 6 条 / §10.2):战斗创建时由 match 按
/// 单一策略表决定、随 CreateBattleRequest 冻结,之后不变。match 的登记公开、两条 WatchBattle 路径、
/// 观战列表与 battle 的 AddObserver 四处都按它执法。默认拒绝:未填(UNSPECIFIED)与 PRIVATE 一样不可观战。
/// </summary>
public enum eSpectateVisibility {
  /// <summary>
  /// 视同私密(老发送方 / 漏填一律 fail-closed)
  /// </summary>
  [pbr::OriginalName("SPECTATE_VISIBILITY_UNSPECIFIED")] SpectateVisibilityUnspecified = 0,
  /// <summary>
  /// 不可观战:计分局、切磋、活动局、自定义房间与未知模式
  /// </summary>
  [pbr::OriginalName("SPECTATE_VISIBILITY_PRIVATE")] SpectateVisibilityPrivate = 1,
  /// <summary>
  /// 任何在线玩家可观战,进观战列表与随机观战
  /// </summary>
  [pbr::OriginalName("SPECTATE_VISIBILITY_PUBLIC")] SpectateVisibilityPublic = 2,
}

/// <summary>
/// 观战投递档位(battle-spectate-tiered-fanout.md §3 / §15):按场只升不降,match 是档位的记账方,
/// battle 只认「挂了哪些中继 gate」与「是否已升广播」两件事。
/// </summary>
public enum eSpectateTier {
  /// <summary>
  /// L0:观众凭票直连 battle(直连席未满)
  /// </summary>
  [pbr::OriginalName("SPECTATE_TIER_DIRECT")] SpectateTierDirect = 0,
  /// <summary>
  /// L1:直连席已满,battle 每回合给每台挂了观众的 gate 各发一条中继帧
  /// </summary>
  [pbr::OriginalName("SPECTATE_TIER_RELAY")] SpectateTierRelay = 1,
  /// <summary>
  /// L2:全服广播,battle 每回合只往广播 topic 发一条,所有 gate 都读
  /// </summary>
  [pbr::OriginalName("SPECTATE_TIER_BROADCAST")] SpectateTierBroadcast = 2,
}

